layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 v_color;
in vec2 v_nodeUV;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform TUNNEL {
  float u_width;
  float u_height;
  float u_vignetteStrength;
  float u_cloudStrength;
  float u_starStrength;
  float u_coreStrength;
  float u_distortStrength;
  float u_opacity;
};
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
}
float fbm(vec2 p) {
    float f = 0.0;
    float amp = 0.5;
    vec2 shift = vec2(0.1);
    for (int i = 0; i < 5; i++) {
        f += amp * noise(p);
        p = p * 2.0 + shift;
        amp *= 0.5;
    }
    return f;
}
vec4 frag () {
  float t = mod(cc_time.x, 30.0);
  float aspect = u_width / u_height;
  vec2 rawUV = vec2(v_nodeUV.x / max(aspect, 0.001), v_nodeUV.y);
  vec2 coord = (rawUV - 0.5) * 2.0;
  vec2 u = 0.2 * vec2(coord.x * aspect, coord.y);
  float radiusOrig = length(u);
  u *= 1.0 + u_distortStrength / (1.0 + u_distortStrength) * sin(radiusOrig * 5.0 - 1.6);
  vec4 z = vec4(1.0, 2.0, 3.0, 0.0);
  vec4 o = z;
  vec2 v = vec2(0.0);
  float a = 0.5;
  for (float i = 0.0; i < 19.0; ++i) {
      float loop_i = i + 1.0;
      if (loop_i >= 19.0) break;
      vec4 mVec = cos(vec4(loop_i + 0.02 * t) - z.wxzw * 11.0);
      mat2 m = mat2(mVec.xy, mVec.zw);
      u *= m;
      float denomRaw = 0.5 - dot(u, u);
      float denom = (denomRaw < 0.0 ? -1.0 : 1.0) * max(abs(denomRaw), 0.001);
      vec2 sinArg = 1.5 * u / denom - 9.0 * u.yx + vec2(t);
      float lenVal = max(0.001, length((1.0 + loop_i * dot(v, v)) * sin(sinArg)));
      o += (1.0 + cos(z + t)) / lenVal;
      v = cos(vec2(++t) - 7.0 * u * pow(a += 0.03, loop_i)) - 5.0 * u;
      vec2 tanhArg = clamp(40.0 * dot(u, u) * cos(100.0 * u.yx + vec2(t)), -20.0, 20.0);
      vec2 tanhExp = exp(2.0 * tanhArg);
      vec2 tanhVal = (tanhExp - 1.0) / (tanhExp + 1.0);
      float oExpArg = min(dot(o, o) / 100.0, 20.0);
      u += tanhVal / 200.0 + 0.2 * a * u + vec2(cos(4.0 / exp(oExpArg) + t) / 300.0);
  }
  o = 25.6 / (min(o, 13.0) + 164.0 / max(abs(o), 0.001));
  vec2 cloudUV = rawUV * 2.5 + t * 0.03;
  float cloud = fbm(cloudUV);
  vec3 cloudColor = mix(vec3(0.08, 0.02, 0.15), vec3(0.2, 0.08, 0.3), cloud);
  float cloudMix = cloud * u_cloudStrength;
  o.rgb = mix(o.rgb, cloudColor, cloudMix * 0.8);
  float star = 0.0;
  float dist = length(rawUV - 0.5);
  for (int j = 0; j < 12; j++) {
      float angle = float(j) * 2.399 + t * 0.3;
      float ringR = 0.32 + 0.04 * sin(angle * 5.0 + t);
      float ringDist = abs(dist - ringR);
      star += exp(-80.0 * ringDist * ringDist);
  }
  vec3 starColor = vec3(1.0, 0.8, 0.3);
  star = clamp(star, 0.0, 1.0) * u_starStrength;
  o.rgb = mix(o.rgb, starColor, star * 0.5);
  float core = exp(-30.0 * dist * dist);
  float pulse = 0.7 + 0.3 * sin(t * 3.0);
  vec3 coreColor = vec3(0.7, 0.4, 0.95);
  o.rgb += coreColor * core * pulse * u_coreStrength * 0.5;
  o.rgb = clamp(o.rgb, 0.0, 1.0);
  float vignetteAlpha = 1.0 - dot(u, u) / 250.0 * u_vignetteStrength;
  vignetteAlpha = clamp(vignetteAlpha, 0.0, 1.0);
  vec4 color = vec4(o.rgb, vignetteAlpha * u_opacity);
  return color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

